// machines/plaits: NOISE's sample loops (engines/noise.c), hand-written SISD kernels.
// Generated by lib/gen_noise_kernel.py; do not edit by hand.
//
// clocked_kernel(ClockedNoise *c, unsigned int *rng, float *k, float *out, int size): clocked_render's loop.
//   c = (phase_, sample_, next_sample_, frequency_); k[0] = the frequency interpolator's increment, k[1] = 2^23 (the
//   bits 0x4B000000), k[2] = 65536.0f, k[3] = 4294967296.0f, k[4] = 2.0f; k[5] is written (selcc's reciprocal of
//   2^32 after its two Newton steps). Writes `size` samples to out, the state back and *rng.
// noise_filter_kernel(Noise *s, const float *k, float *out, float *aux, const float *temp, int size): noise_render's
//   filter loop; k[0..3] = the increments of previous_f0_, previous_f1_, previous_q_, previous_mode_. aux holds the
//   first clocked noise on entry, temp the second; out and aux receive the filters' outputs.
// Both bit-identical to selcc's code of the C (-DPL_NOISE_C): the same operations with the same operands in the same
// order (tests/plaits/test_noise_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, I2, I3, M6, L0-L4 pushed through R0, M6 = 1 and L0-L4 = 0 set here). No SIMD.
//
// ABI: as the other kernels (lib/wavetable_sm.s): relies on M5 = 0 and M7 = -1, sets M6 = 1 itself; DAG registers
// are pushed through R0 and restored by loads through I7. Assembled under .COMPRESS.

.SECTION/PM seg_pmco;
.GLOBAL clocked_kernel.;
.GLOBAL noise_filter_kernel.;
.COMPRESS;

clocked_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = I3;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L3;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L3 = 0;
    L4 = 0;
    I7=MODIFY (I7,-7)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // c
    I2 = R8;                                            // rng
    I4 = R12;                                           // k
    R0 = DM(1, I6);                                     // out
    I0 = R0;
    R0 = DM(2, I6);                                     // size
    DM(7, I7) = R0;
    R8 = DM(3, I4);
    R4 = DM(4, I4);
    F9 = RECIPS F8;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    DM(5, I4) = R9;
    R9 = DM(0, I4);                                     // the increment
    R13 = DM(I2, M5);                                   // rng
    R15 = DM(0, I1);                                    // phase_
    R14 = DM(1, I1);                                    // sample_
    R11 = DM(2, I1);                                    // next_sample_
    R10 = DM(3, I1);                                    // frequency_ (the interpolator's value)
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _ck_done;
_ck_loop:
    R12 = PASS R11;                                     // this_sample = next_sample
    R11 = 0;                                            // next_sample = 0.0f
    F10 = F10 + F9;                                     // freq = fm.Next()
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(1, I4);               // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
    R8 = FEXT R13 BY 0:16;                              // w & 0xFFFF
    R7 = R7 OR R6;                                      // itof_nonneg
    R8 = R8 OR R6;
    F7 = F7 - F6, R5 = DM(2, I4);
    F8 = F8 - F6;
    F7 = F7 * F5, R5 = DM(5, I4);                       // hi * 65536.0f
    F7 = F7 + F8, R6 = DM(3, I4);                       // + lo
    F8 = F7 * F5;                                       // / 4294967296.0f: q
    F4 = F6 * F8;
    F4 = F7 - F4;
    F4 = F4 * F5;
    F3 = F8 + F4;
    R0 = 0x40000000;
    F3 = F3 * F0;                                       // raw_sample = rng_float(rng) * 2.0f - 1.0f
    R0 = 0x3F800000;
    F3 = F3 - F0;
    R0 = 0x3E800000;
    F1 = F10 - F0;                                      // raw_amount = 4.0f * (freq - 0.25f)
    R0 = 0x40800000;
    F1 = F0 * F1;
    R0 = 0;
    COMP(F1, F0);                                       // CONSTRAIN(raw_amount, 0.0f, 1.0f)
    IF LT R1 = R0 OR R0;
    R0 = 0x3F800000;
    COMP(F1, F0);
    IF GT R1 = R0 OR R0;
    F15 = F15 + F10;                                    // phase_ += freq
    COMP(F15, F0);                                      // phase_ >= 1.0f
    IF LT JUMP _ck_nr;
    F15 = F15 - F0;                                     // phase_ -= 1.0f
    R4 = 0x40000000;
    F5 = RECIPS F10;
    F6 = F10 * F5;                                      // t = phase_ / freq
    F6 = F4 - F6;
    F5 = F5 * F6;
    F6 = F10 * F5;
    F6 = F4 - F6;
    F5 = F5 * F6;
    F4 = F15 * F5;
    F6 = F10 * F4;
    F6 = F15 - F6;
    F6 = F6 * F5;
    F2 = F4 + F6;
    F0 = F3 - F14;                                      // discontinuity = new_sample - sample
    R4 = 0x3F000000;
    F4 = F4 * F2;                                       // ThisBlepSample(t)
    F4 = F4 * F2;
    F4 = F0 * F4;
    F12 = F12 + F4;                                     // this_sample += discontinuity * ..
    R5 = 0x3F800000;
    F5 = F5 - F2;                                       // NextBlepSample(t)
    R4 = 0xBF000000;
    F4 = F4 * F5;
    F4 = F4 * F5;
    F4 = F0 * F4;
    F11 = F11 + F4;                                     // next_sample += discontinuity * ..
    R14 = PASS R3;                                      // sample = new_sample
_ck_nr:
    F11 = F11 + F14;                                    // next_sample += sample
    F0 = F3 - F12;                                      // out[i] = this_sample + raw_amount * (raw_sample - this_sample)
    F0 = F1 * F0;
    F0 = F12 + F0;
    DM(I0, M6) = R0;
    R0 = DM(7, I7);
    R1 = 1;
    R0 = R0 - R1;
    DM(7, I7) = R0;
    IF NE JUMP _ck_loop;
_ck_done:
    DM(0, I1) = R15;
    DM(1, I1) = R14;
    DM(2, I1) = R11;
    DM(3, I1) = R10;
    DM(I2, M5) = R13;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,7)(NW);
    L4 = DM(1, I7);
    L3 = DM(2, I7);
    L2 = DM(3, I7);
    L1 = DM(4, I7);
    L0 = DM(5, I7);
    M6 = DM(6, I7);
    I3 = DM(7, I7);
    I2 = DM(8, I7);
    I1 = DM(9, I7);
    I0 = DM(10, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

