    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = I3;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L3;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L3 = 0;
    L4 = 0;
    I7=MODIFY (I7,-21)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(1, I6);                                     // aux
    I2 = R0;
    R0 = DM(2, I6);                                     // temp
    I3 = R0;
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(2, I4);
    DM(9, I7) = R0;
    R0 = DM(3, I4);
    DM(10, I7) = R0;
    R0 = DM(3, I6);                                     // size
    DM(11, I7) = R0;
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _nf_done;
_nf_loop:
    R13 = DM(23, I1);
    R0 = DM(7, I7);
    F13 = F13 + F0;                                     // g_f0 = f0_modulation.Next()
    DM(23, I1) = R13;
    R14 = DM(24, I1);
    R0 = DM(8, I7);
    F14 = F14 + F0;                                     // g_f1
    DM(24, I1) = R14;
    R15 = DM(25, I1);
    R0 = DM(9, I7);
    F15 = F15 + F0;                                     // g_q
    DM(25, I1) = R15;
    R0 = 0x3F000000;
    F1 = F0 + F15;                                      // (0.5f + g_q) * 40.0f * g_f0
    R2 = 0x42200000;
    F1 = F1 * F2;
    F1 = F1 * F13;
    F3 = F0 * F1;                                       // pl_rsqrt: h = 0.5f * x
    R2 = 0;
    COMP(F1, F2);                                       // x > 0.0f
    IF GT JUMP _nf_rs;
    R12 = 0;                                            // gain = 0.0f
    JUMP _nf_rd;
_nf_rs:
    R2 = -1;
    R1 = ASHIFT R1 BY R2;                               // 0x5f3759df - (bits >> 1)
    R2 = 0x5F3759DF;
    R12 = R2 - R1;
    R0 = 0x3FC00000;
    F1 = F3 * F12;                                      // y = y * (1.5f - h * y * y)
    F1 = F1 * F12;
    F1 = F0 - F1;
    F12 = F12 * F1;
    F1 = F3 * F12;                                      // y = y * (1.5f - h * y * y)
    F1 = F1 * F12;
    F1 = F0 - F1;
    F12 = F12 * F1;
    F1 = F3 * F12;                                      // y = y * (1.5f - h * y * y)
    F1 = F1 * F12;
    F1 = F0 - F1;
    F12 = F12 * F1;
