    F4 = F14 * F14;                                     // tan_accurate: f2
    R5 = 0x452EFE23;
    F5 = F4 * F5;
    R6 = 0x42ACEC90;
    F5 = F6 + F5;
    F5 = F4 * F5;
    R6 = 0x4321348F;
    F5 = F6 + F5;
    F5 = F4 * F5;
    R6 = 0x42234865;
    F5 = F6 + F5;
    F5 = F4 * F5;
    R6 = 0x41255DA9;
    F5 = F6 + F5;
    F5 = F4 * F5;
    R6 = 0x40490FDB;
    F5 = F6 + F5;
