    F4 = F10 * F9;
    R5 = 0x3F800000;
    F4 = F5 + F4;
    F6 = F9 * F9;
    F4 = F4 + F6;
    R11 = 0x40000000;
    F6 = RECIPS F4;
    F7 = F4 * F6;                                       // selcc division
