    F0 = F0 * F12;                                      // input_1 = aux[i] * gain
    DM(17, I7) = R0;
    R0 = DM(I3, M6);
    F0 = F0 * F12;                                      // input_2 = temp[i] * gain
    DM(18, I7) = R0;
    R0 = DM(26, I1);
    R1 = DM(10, I7);
