    R12 = PASS R1;                                      // b0
    R9 = DM(15, I7);
    R11 = DM(16, I7);
    R8 = DM(18, I7);
    R0 = DM(21, I1);                                    // svf_step: state_1_
    R1 = DM(22, I1);                                    // state_2_
